<script setup lang="ts">import{ref}from'vue';import{useForm,usePage}from'@inertiajs/vue3';import MainLayout from'../../Layouts/MainLayout.vue';const p=defineProps<{items:any[];activeClass:any}>(),page=usePage(),edit=ref<any>(null),f=useForm({nis:'',nama:'',kontak:''});const reset=()=>{edit.value=null;f.reset()};const load=(x:any)=>{edit.value=x;f.nis=x.nis;f.nama=x.nama;f.kontak=x.kontak??''};const save=()=>edit.value?f.patch(`/master/siswa/${edit.value.id}`,{onSuccess:reset}):f.post('/master/siswa',{onSuccess:reset});const remove=(id:number)=>confirm('Hapus siswa ini?')&&useForm({}).delete(`/master/siswa/${id}`);const rp=(v:any)=>Number(v??0).toLocaleString('id-ID');</script>
<template><MainLayout><main class="p-4 sm:p-6 lg:p-8"><div class="mx-auto max-w-7xl"><div v-if="page.props.flash?.success" class="mb-4 rounded-lg bg-emerald-50 p-3 text-sm text-emerald-700">{{page.props.flash.success}}</div><div v-if="page.props.flash?.error" class="mb-4 rounded-lg bg-rose-50 p-3 text-sm text-rose-700">{{page.props.flash.error}}</div><div class="mb-6"><p class="text-sm font-bold uppercase tracking-widest text-indigo-600">Master data</p><h1 class="mt-2 text-2xl font-bold">Siswa</h1><p class="mt-1 text-sm text-slate-500">Kelas aktif: {{p.activeClass?.nama_kelas??'Belum diatur'}} · {{p.activeClass?.tahun_pelajaran?.tahun??''}}</p></div><section class="sneat-card p-5 sm:p-6"><div class="flex items-center justify-between"><div><h2 class="font-bold">{{edit?'Edit siswa':'Tambah siswa'}}</h2><p class="mt-1 text-xs text-slate-500">Data otomatis masuk ke kelas aktif.</p></div><button v-if="edit" @click="reset" class="text-sm font-semibold text-indigo-600">Batal edit</button></div><form @submit.prevent="save" class="mt-5 space-y-4"><div><label class="mb-2 block text-sm font-medium">NIS</label><input v-model="f.nis" class="w-full" placeholder="Masukkan NIS" required><p v-if="f.errors.nis" class="mt-1 text-xs text-rose-600">{{f.errors.nis}}</p></div><div><label class="mb-2 block text-sm font-medium">Nama lengkap</label><input v-model="f.nama" class="w-full" placeholder="Masukkan nama siswa" required></div><div><label class="mb-2 block text-sm font-medium">Kontak <span class="font-normal text-slate-400">(opsional)</span></label><input v-model="f.kontak" class="w-full" placeholder="Nomor kontak"></div><button :disabled="f.processing" class="sneat-primary w-full rounded-lg px-4 py-3 text-sm font-semibold text-white">{{f.processing?'Menyimpan…':edit?'Simpan perubahan':'Simpan siswa'}}</button></form></section><section class="sneat-card mt-6 overflow-hidden"><div class="border-b p-5"><h2 class="font-bold">Daftar siswa</h2><p class="mt-1 text-xs text-slate-500">{{p.items.length}} siswa pada kelas aktif</p></div><div class="overflow-x-auto"><table class="sneat-table w-full text-left text-sm"><thead class="text-xs uppercase"><tr><th class="p-4">NIS</th><th class="p-4">Nama</th><th class="p-4">Kontak</th><th class="p-4">Saldo tabungan</th><th class="p-4 text-right">Aksi</th></tr></thead><tbody class="divide-y"><tr v-for="x in p.items" :key="x.id"><td class="p-4">{{x.nis}}</td><td class="p-4 font-semibold">{{x.nama}}</td><td class="p-4 text-slate-500">{{x.kontak||'—'}}</td><td class="p-4 font-semibold text-emerald-600">Rp {{rp(x.saldo_total)}}</td><td class="space-x-2 p-4 text-right"><button @click="load(x)" class="rounded bg-indigo-50 px-3 py-2 text-xs font-semibold text-indigo-600">Edit</button><button v-if="!x.transaksi_count" @click="remove(x.id)" class="rounded bg-rose-50 px-3 py-2 text-xs font-semibold text-rose-600">Hapus</button></td></tr><tr v-if="!p.items.length"><td colspan="5" class="p-10 text-center text-slate-400">Belum ada siswa.</td></tr></tbody></table></div></section></div></main></MainLayout></template>
